"""Trust only identity metadata generated by the Supervisor Ingress proxy.

Supervisor 2026.10.4+ removes caller-supplied identity headers and injects
effective user groups. The service credential is deliberately irrelevant here.
The ASGI server must retain the actual transport peer (--no-proxy-headers).
"""

import re
from dataclasses import dataclass

from fastapi import HTTPException, Request

SUPERVISOR_INGRESS_PEER = "172.30.32.2"


@dataclass(frozen=True)
class IngressIdentity:
    user_id: str
    path: str


def _single_header(request: Request, name: str) -> str:
    values = request.headers.getlist(name)
    if len(values) != 1 or not values[0] or len(values[0]) > 1024:
        raise HTTPException(403, "Ingress access denied")
    return values[0]


def verified_identity(request: Request) -> IngressIdentity:
    if request.client is None or request.client.host != SUPERVISOR_INGRESS_PEER:
        raise HTTPException(403, "Ingress access denied")
    path = _single_header(request, "x-ingress-path")
    user_id = _single_header(request, "x-remote-user-id")
    groups = _single_header(request, "x-remote-user-groups").split(",")
    if (
        re.fullmatch(r"/api/hassio_ingress/[A-Za-z0-9_-]{1,256}", path) is None
        or re.fullmatch(r"[0-9a-f]{32}", user_id) is None
        or any(re.fullmatch(r"[A-Za-z0-9_-]{1,64}", group) is None for group in groups)
        or len(set(groups)) != len(groups)
        or "system-admin" not in groups
    ):
        raise HTTPException(403, "Ingress access denied")
    return IngressIdentity(user_id=user_id, path=path)
